<template><main class="success-page"><div class="container py-5"><RentalBookingSuccess :number="shortId"><div class="next-card"><span>Estado</span><strong>{{ statusSummary }}</strong><p>Ahora validaremos la disponibilidad y prepararemos el equipo. Te informaremos cada avance.</p><small>Próximo paso · Validación administrativa</small></div><div class="d-flex gap-2 flex-wrap justify-content-center"><RouterLink to="/mi-cuenta/alquileres" class="btn btn-primary">Ver mis alquileres</RouterLink><RouterLink to="/alquiler" class="btn btn-outline-primary">Volver al catálogo</RouterLink><RouterLink to="/" class="btn btn-link">Continuar navegando</RouterLink><button class="btn btn-outline-secondary" @click="print"><i class="bi bi-download me-1"></i>Descargar comprobante</button></div></RentalBookingSuccess></div></main></template>
<script setup>import{computed,onMounted}from'vue';import{useRoute}from'vue-router';import RentalBookingSuccess from '@/components/customer/renting/RentalBookingSuccess.vue';import{useEnums}from '@/composables/useEnums';const route=useRoute();const enums=useEnums();const shortId=computed(()=>String(route.params.uuid).slice(0,8).toUpperCase());const paymentMethod=computed(()=>String(route.query.payment||'WOMPI').toUpperCase());const statusSummary=computed(()=>{if(paymentMethod.value==='COD'){return `Confirmada · ${enums.label('payment-methods','COD','Pago contra entrega').toLowerCase()}`;}const approved=enums.label('payment-statuses','APPROVED','Aprobado');const method=enums.label('payment-methods',paymentMethod.value,'Pago recibido');return `${approved} · ${method}`;});const print=()=>window.print();onMounted(()=>{enums.preload(['payment-statuses','payment-methods']);});</script>
<style scoped>.success-page{min-height:100vh;background:#f8f8fb}.next-card{background:#fff;border:1px solid #e8e7ee;border-radius:20px;padding:1.4rem;text-align:left;margin:1.2rem auto 1.5rem;max-width:580px}.next-card span,.next-card small{display:block;color:#64748b}.next-card strong{display:block;font-size:1.2rem;color:#15803d;margin:.25rem 0 .8rem}</style>
